    for c in range(inner_left+1,inner_right):
        out[inner_top+1][c] = 4
        out[inner_bottom-1][c] = 4
    for r in range(inner_top+1,inner_bottom):
        out[r][inner_left+1] = 4
        out[r][inner_right-1] = 4
    # Preserve any interior marker from the input after the pattern fill.
    for r in range(top+1,bottom):
        for c in range(left+1,right):
            if grid[r][c] == 3:
                out[r][c] = 3
